if (msg.retain === true) return null;
let p = msg.payload;
try { if (typeof p === 'string') p = JSON.parse(p); } catch { return null; }
if (!p || typeof p !== 'object' || Array.isArray(p)) return null;
const num = (v,lo,hi) => typeof v === 'number' && Number.isFinite(v) && v >= lo && v <= hi ? v : null;
const bool = v => v === true || v === 1 ? true : v === false || v === 0 ? false : null;
const now = Date.now();
const timestamp = new Date(now).toISOString();
if (msg.topic === 'smarthome/esp32/sensor/state') {
    if (!('dht_ok' in p) || !('motion' in p)) return null;
    const temp = num(p.temperature,-40,80), humid = num(p.humidity,0,100);
    const valid = bool(p.dht_ok) === true && temp !== null && humid !== null;
    const demoLux = function demoLux(adc) {
  if (!Number.isInteger(adc) || adc < 0 || adc > 4095) return { lux: null, quality: 'INVALID_ADC' };
  // Moc phong bat den 10/11/2026: trung vi ADC 3916 -> 400 lux gia dinh.
  // Giu chieu ADC giam khi sang hon; noi suy giua cac moc trinh dien.
  const points = [[0, 1500], [2850, 700], [3916, 400], [4095, 100]];
  const index = points.findIndex((point, i) => i > 0 && adc <= point[0]);
  const [a, lowerLux] = points[index - 1];
  const [b, upperLux] = points[index];
  const lux = lowerLux + (adc - a) * (upperLux - lowerLux) / (b - a);
  return { lux: Number(lux.toFixed(2)), quality: adc === 0 || adc === 4095 ? 'DEMO_ADC_LIMIT' : 'DEMO_ASSUMPTION' };
};
    const light = demoLux(p.ldr_adc);
    const r = {device_id:'node1_sensor', temp:valid ? temp : null, humid:valid ? humid : null,
        lux:light.lux, lux_estimated:true, lux_demo:true, lux_method:'DEMO_ROOM_LIGHT_V2', lux_quality:light.quality, occupancy:bool(p.pir_ready) === true ? bool(p.motion) : null,
        ldr_adc:num(p.ldr_adc,0,4095), light_percent:num(p.light_percent,0,100),
        connected:true, timestamp};
    flow.set('scSensor',{at:now,record:r});
    // Store the agreed demo-scale lux for backend automation testing; not calibrated lux.
    const localTime = new Date(now + 7*3600000).toISOString().slice(0,19).replace('T',' ');
    const sql = {topic:'INSERT INTO telemetry (device_id,temp,humid,lux,occupancy,`timestamp`) VALUES (?,?,?,?,?,?)',
        payload:[r.device_id,r.temp,r.humid,r.lux,r.occupancy === null ? null : Number(r.occupancy),localTime]};
    return [{payload:r},sql];
}
if (msg.topic === 'smarthome/esp32/relay/state') {
    const fan=bool(p.fan_on), light=bool(p.light_on);
    if (fan === null || light === null) return null;
    const modes=['AUTO','MANUAL_ON','MANUAL_OFF'];
    const fanMode=modes.includes(p.fan_mode) ? p.fan_mode : null;
    const lightMode=modes.includes(p.light_mode) ? p.light_mode : null;
    const r={device_id:'node2_actuator',FAN:fan,LIGHT:light,connected:true,timestamp,
        AUTO:fanMode === null || lightMode === null ? null : fanMode === 'AUTO' && lightMode === 'AUTO',
        fan_mode:fanMode,light_mode:lightMode,uart_ok:bool(p.uart_ok)};
    flow.set('scRelay',{at:now,record:r});
    return [{payload:r},null];
}
return null;

const now=Date.now();
const read=(key,id,fields) => {
    const c=flow.get(key);
    if (c && now >= c.at && now-c.at < 10000) return c.record;
    return {device_id:id,...fields,connected:false,timestamp:c ? c.record.timestamp : null};
};
msg.headers={'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'};
msg.statusCode=200;
msg.payload={devices:[
    read('scSensor','node1_sensor',{temp:null,humid:null,lux:null,occupancy:null,ldr_adc:null,light_percent:null}),
    read('scRelay','node2_actuator',{FAN:null,LIGHT:null,AUTO:null})
]};
return msg;
